import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { changeFilters, filterChanges, percentageChange, previewEnabled, previewState, type DisplayChangesState } from "../lib/changes-preview.ts";
import { publishedChange } from "../lib/changes.ts";
// Explicitly synthetic checked-in transport fixture, generated by the real detector.
// Python tests in the root repo verify it stays identical to the producer.
const raw = JSON.parse(readFileSync(new URL("./fixtures/changes-preview.json", import.meta.url), "utf8"));
const all = changeFilters({});
test("synthetic preview requires explicit development opt-in", () => {
  assert.equal(previewEnabled({ NODE_ENV: "development", CHANGES_LOCAL_PREVIEW: "1" }), true);
  for (const NODE_ENV of ["production", "test", undefined]) assert.equal(previewEnabled({ NODE_ENV, CHANGES_LOCAL_PREVIEW: "1" }), false);
  assert.equal(previewEnabled({ NODE_ENV: "development" }), false);
});
test("Python detector fixture yields both directions and chronological cards", () => {
  const state = previewState(raw, all);
  assert.equal(state.status, "ready");
  assert.ok(state.items.some(i => i.evidence.direction === "above"));
  assert.ok(state.items.some(i => i.evidence.direction === "below"));
  assert.ok(state.items.every(i => i.provider === "deterministic"));
  const times = state.items.map(i => i.evidence.observation_timestamp);
  assert.deepEqual(times, [...times].sort().reverse());
});
test("metric, direction, campaign and inclusive dates select independently", () => {
  const s = previewState(raw, changeFilters({ campaign: "1458", metric: "clicks", direction: "above", from: "2013-06-07", to: "2013-06-07" }));
  assert.ok(s.items.length > 0);
  assert.ok(s.items.every(i => i.evidence.metric === "clicks" && i.evidence.advertiser_id === "1458" && i.evidence.direction === "above"));
  assert.equal(previewState(raw, changeFilters({ from: "2013-06-08", to: "2013-06-08" })).status, "empty");
  assert.ok(changeFilters({ metric: "revenue" }).error);
  assert.ok(changeFilters({ direction: ["above"] }).error);
  assert.ok(changeFilters({ campaign: "invalid" }).error);
});
test("first day has insufficient history; constants and missing hours are explicit", () => {
  const first = previewState(raw, changeFilters({ from: "2013-06-06", to: "2013-06-06" }));
  assert.equal(first.status, "insufficient_history");
  const all = previewState(raw, changeFilters({}));
  assert.ok(all.preview!.diagnostics.zero_variance > 0);
  assert.ok(all.preview!.diagnostics.missing_coverage > 0);
});
test("percentage calculation handles zero, nonfinite, positive and negative baselines", () => {
  assert.equal(percentageChange(20, 10), "+100%");
  assert.equal(percentageChange(5, 10), "-50%");
  assert.equal(percentageChange(1, 0), "Not defined (zero baseline)");
  assert.equal(percentageChange(0, 0), "Not defined (zero baseline)");
  assert.equal(percentageChange(1, -1), "Unavailable");
  assert.equal(percentageChange(Infinity, 1), "Unavailable");
});
test("malformed fixture fails closed and cannot become a published AI result", () => {
  assert.equal(previewState({ source: "live", results: [] }, all).status, "error");
  const state = previewState(raw, all);
  for (const item of state.items) assert.equal(publishedChange({ ...item, job_id: item.id, publication_status: "publishable" }), null);
  const original = structuredClone(raw);
  previewState(raw, all);
  assert.deepEqual(raw, original);
});
test("existing live states survive filters without becoming synthetic", () => {
  for (const status of ["unconfigured", "error"] as const) {
    const state: DisplayChangesState = { status, items: [], omitted: 0, limited: false };
    assert.equal(filterChanges(state, all).status, status);
    assert.equal(filterChanges(state, all).preview, undefined);
  }
});
